insert into public.settings (id, data) values (1, '{"brand":{"name":"COVE","city":"Doha","timezone":"Asia/Qatar","established":"2019"},"hero":{"eyebrow":"Photography & direction","tagline":"Photographer and visual director working between commissioned work and quiet, personal studies of light, form and the people inside them.","specialties":["Portrait","Editorial","Still life"]},"contact":{"email":"hello@cove.studio","phone":"+974 5500 0000","instagram":"@cove.studio","instagramUrl":"https://www.instagram.com/"},"manifesto":{"label":"Approach","text":"We photograph the *quiet* between moments — light falling on a wall, the weight of a shadow, the shape a person leaves behind. Nothing more than it needs to be."},"work":{"title":"Selected\n*work*","label":"2024—2026"},"latest":{"title":"The *latest*","label":"Recent commissions"},"archive":{"title":"Arch*ive*","filters":[{"key":"editorial","label":"Editorial"},{"key":"studio","label":"Studio"},{"key":"street","label":"Street"},{"key":"detail","label":"Detail"}]},"about":{"label":"About the studio","text":"COVE is a one-person photography studio making images for brands, magazines and musicians — slow, considered and made to *last.*","portraitUrl":"images/fashion-02.jpg","services":[{"name":"Portrait","meta":"01"},{"name":"Editorial & fashion","meta":"02"},{"name":"Still life & product","meta":"03"},{"name":"Architecture","meta":"04"},{"name":"Art direction","meta":"05"}],"recognition":[{"name":"Monochrome Awards","meta":"2025"},{"name":"Solo show — Gallery 7","meta":"2025"},{"name":"Book: *Low Light*","meta":"2024"},{"name":"Young Talent shortlist","meta":"2023"}]},"footer":{"title":"Let’s make\nsomething *quiet.*","blocks":[{"title":"Studio","lines":["COVE Studio","West Bay, Doha, Qatar"]},{"title":"Enquiries","lines":["hello@cove.studio","+974 5500 0000"]}],"socials":[{"label":"Instagram","url":"https://www.instagram.com/"},{"label":"Behance","url":"https://www.behance.net/"}],"copyright":"© 2026 COVE Studio"}}'::jsonb)
